const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await ee.data.authenticateViaPrivateKey(privateKey);
  await ee.initialize();

  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Rectangle([-160, 25, -120, 55]); // Northeastern Pacific Ocean
  const collectionId = 'NOAA/AVHRR/Pathfinder_V5_3/L3C';
  const scale = 5000; // Use a coarse scale to avoid memory issues and speed up

  // Function to filter and calculate monthly SST mean
  const getMonthlySST = (year, month, geom) => {
    let startDate = ee.Date.fromYMD(year, month, 1);
    let endDate = startDate.advance(1, 'month');

    let collection = ee.ImageCollection(collectionId)
      .filterBounds(geom)
      .filterDate(startDate, endDate)
      .select(['sst', 'quality_level']);

    // Check if collection is empty
    if (collection.size().getInfo() === 0) {
      return null;
    }

    // Filter for good quality pixels (quality_level <= 2)
    // and then calculate the mean SST for the month
    let monthlyMean = collection.map(image => {
      let mask = image.select('quality_level').lte(2);
      return image.select('sst').updateMask(mask).copyProperties(image, ['system:time_start']);
    }).mean();

    return monthlyMean;
  };

  // 2. Data Acquisition & Check for August 2019
  const sst2019 = getMonthlySST(2019, 8, geometry);

  if (sst2019 === null) {
    console.log("No images found for August 2019.");
    console.log("C1");
    return;
  }

  // Calculate mean for 2019 and check for C2/C3
  const mean2019 = sst2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('sst');

  const count2019 = sst2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('sst');

  const mean2019Value = mean2019.getInfo();
  const count2019Value = count2019.getInfo();

  if (count2019Value === 0 || mean2019Value === null || isNaN(mean2019Value)) {
    console.log(`2019 August SST: ${mean2019Value !== null ? mean2019Value.toFixed(2) : 'N/A'} (Pixels: ${count2019Value})`);
    console.log("No valid pixels or calculation failure for 2019 after masking.");
    console.log(count2019Value === 0 ? "C2" : "C3");
    return;
  }

  // 3. Data Acquisition & Check for Historical Average (1985-2012)
  const historicalYears = ee.List.sequence(1985, 2012);
  const historicalSSTs = historicalYears.map(year => {
    let yearSST = getMonthlySST(year, 8, geometry);
    // If a specific year has no data, return a dummy value to keep the list length consistent,
    // which will be filtered out later or handled in the reducer.
    return ee.Algorithms.If(yearSST, yearSST.select('sst'), ee.Image(0).rename('sst').updateMask(ee.Image(0)));
  }).filter(ee.Filter.notNull('item')); // Filter out any null images from getMonthlySST

  const historicalCollection = ee.ImageCollection(historicalSSTs);

  if (historicalCollection.size().getInfo() === 0) {
    console.log("No images found for historical August average (1985-2012).");
    console.log("C1");
    return;
  }

  const historicalMeanImage = historicalCollection.mean();

  // Calculate mean for historical period and check for C2/C3
  const meanHistorical = historicalMeanImage.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('sst');

  const countHistorical = historicalMeanImage.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9
  }).get('sst');

  const meanHistoricalValue = meanHistorical.getInfo();
  const countHistoricalValue = countHistorical.getInfo();

  if (countHistoricalValue === 0 || meanHistoricalValue === null || isNaN(meanHistoricalValue)) {
    console.log(`Historical August SST: ${meanHistoricalValue !== null ? meanHistoricalValue.toFixed(2) : 'N/A'} (Pixels: ${countHistoricalValue})`);
    console.log("No valid pixels or calculation failure for historical average after masking.");
    console.log(countHistoricalValue === 0 ? "C2" : "C3");
    return;
  }

  // Convert SST values from K * 100 to Celsius
  const sst2019C = (mean2019Value / 100) - 273.15;
  const sstHistoricalC = (meanHistoricalValue / 100) - 273.15;

  console.log(`August 2019 SST (C): ${sst2019C.toFixed(2)} (Pixels: ${count2019Value})`);
  console.log(`Historical August SST (1985-2012) (C): ${sstHistoricalC.toFixed(2)} (Pixels: ${countHistoricalValue})`);

  // 5. Validation & Final Answer
  if (sst2019C === null || isNaN(sst2019C) || sstHistoricalC === null || isNaN(sstHistoricalC)) {
    console.log("C3"); // Should already be caught, but a final check
  } else if (sst2019C < sstHistoricalC) {
    console.log("A"); // Cooler
  } else {
    console.log("B"); // Not cooler (i.e., warmer or same)
  }
}

runAnalysis().catch(e => {
  console.error("Analysis failed: ", e);
  console.log("D"); // Catch other potential errors
});
